# --- Al final, enviar correo ---
def enviar_correo(asunto, Texto_Enciado):
    remitente = "pcaliman@gmail.com"           # Cambiar por tu email
    clave = "glhz qhos bbww sgyc"                                  # Tu contraseña
    
    destinatario = "pcaliman@hotmail.com"
    #destinatario = "pcaliman@hotmail.com, 20110@escopec.cl, brayan@gfv.cl, luis@gfv.cl"
    

    servidor_smtp = "smtp.gmail.com"
    puerto = 587

    try:
        # Crear el mensaje
        mensaje = MIMEMultipart()
        mensaje["From"] = remitente
        mensaje["To"] = destinatario
        mensaje["Subject"] = asunto
        mensaje.attach(MIMEText(Texto_Enciado, "plain"))

        # Conectarse al servidor SMTP
        servidor = smtplib.SMTP(servidor_smtp, puerto)
        servidor.starttls()
        servidor.login(remitente, clave)
        servidor.send_message(mensaje)
        servidor.quit()

        print("✅ Correo enviado correctamente.")
    except Exception as e:
        print("❌ Error al enviar correo:", e)

